unsigned long nodes_mask[1];
unsigned long max_idx = 64;

// Set mask to specify Node 1
nodes_mask[0] = 1UL << 1;

// Mode 1: Bind strictly to nodes in the mask
int mode_bind = MPOL_BIND | MPOL_F_STRICT;

// Mode 2: Preferred allocation from Node 0 (if mask isn't used)
int mode_preferred = MPOL_PREFERRED;

// Apply binding policy to the calling thread
int ret_bind = set_mempolicy(mode_bind, nodes_mask, max_idx);

// Set preferred policy (node specified implicitly via mode or nodemask)
// Note: MPOL_PREFERRED often targets a single node (e.g., node_mask[0] = 0 for Node 0)
// If nodemask is NULL, MPOL_PREFERRED defaults to a system preferred node.
int ret_pref = set_mempolicy(MPOL_PREFERRED, NULL, 0);
